/**
 * @name Path traversal
 * @description Untrusted input flows to a filesystem path argument
 * @kind problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTravConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTravFlow = TaintTracking::Global<PathTravConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTravFlow::flow(source, sink)
select sink, "Path traversal: untrusted input $@ flows to a filesystem path.", source, "user input"

/**
 * @name Header injection via aiohttp response headers
 * @description Untrusted data flowing into HTTP response header values can lead to header/CRLF injection
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-header-injection
 * @tags security
 *       external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call, string attr |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = attr and
      attr in ["add_header", "set_cookie", "append"] and
      sink = call.getArg(1)
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Header injection from $@.", source.getNode(), "user input"

/**
 * @name Open redirect via Location header
 * @description Untrusted data flowing into a redirect Location header can lead to open redirect
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-open-redirect
 * @tags security
 *       external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isLocationHeaderName(DataFlow::Node arg0) {
    exists(DataFlow::Node n |
      n = arg0 and
      (
        n.asExpr().(StrConst).getText() = "Location"
        or
        n.(DataFlow::AttrRead).getAttributeName() = "LOCATION"
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "add_header" and
      isLocationHeaderName(call.getArg(0)) and
      sink = call.getArg(1)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"

/**
 * @name Open redirect in aiohttp web exceptions
 * @description Find redirect constructors whose Location header may be user influenced
 * @kind path-problem
 * @problem.severity warning
 * @id py/open-redirect-aiohttp
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember(["HTTPFound", "HTTPMovedPermanently", "HTTPTemporaryRedirect", "HTTPSeeOther", "HTTPPermanentRedirect"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"

